-- Self-referencing table(s): 'MT_RSTD_BKGS_MEASURE' used as both source and target in this mapping.
-- Materialized as TABLE to snapshot source data before the target model overwrites it.
-- Pre/Post SQL hooks: the orchestration task may override these defaults at runtime via dbt --vars.
{% set pre_sql = var('m_WI1_RSTD_BKGS_ORDER_MTH_sq_wi1_rstd_bkgs_order_mth_pre_sql', '') %}
{% if pre_sql != '' %}
  {{ config(pre_hook=pre_sql) }}
{% endif %}
-- Mapping-level SQL Query override (from Source Qualifier 'Sql Query' property)
SELECT
   CASE
      WHEN A.SALES_ORDER_KEY >= -1006800
      AND A.SALES_ORDER_KEY <= -1005000
         THEN -8888
      WHEN A.SALES_ORDER_KEY >= -1001800
      AND A.SALES_ORDER_KEY <= -1000000
         THEN -9999
      WHEN A.SALES_ORDER_KEY >= -1011800
      AND A.SALES_ORDER_KEY <= -1010000
         THEN -7777 /*added as part of Q1FY15 rel*/
      ELSE A.SALES_ORDER_KEY
   END SALES_ORDER_KEY,
   CASE
      WHEN A.PRODUCT_KEY >= -1006800
      AND A.PRODUCT_KEY <= -1005000
         THEN -998
      WHEN A.PRODUCT_KEY >= -1001800
      AND A.PRODUCT_KEY <= -1000000
         THEN -999
      ELSE A.PRODUCT_KEY
   END PRODUCT_KEY,
   CASE
      WHEN A.AR_TRX_KEY >= -1006800
      AND A.AR_TRX_KEY <= -1005000
         THEN -8888
      WHEN A.AR_TRX_KEY >= -1001800
      AND A.AR_TRX_KEY <= -1000000
         THEN -9999
      WHEN A.AR_TRX_KEY >= -1011800
      AND A.AR_TRX_KEY <= -1010000
         THEN -7777 /*added as part of Q1FY15 rel*/
      ELSE A.AR_TRX_KEY
   END AR_TRX_KEY,
   CASE
      WHEN A.BILL_TO_CUSTOMER_KEY >= -1001800
      AND A.BILL_TO_CUSTOMER_KEY <= -1000000
         THEN -999
      ELSE A.BILL_TO_CUSTOMER_KEY
   END BILL_TO_CUSTOMER_KEY,
   CASE
      WHEN A.SHIP_TO_CUSTOMER_KEY >= -1001800
      AND A.SHIP_TO_CUSTOMER_KEY <= -1000000
         THEN -999
      ELSE A.SHIP_TO_CUSTOMER_KEY
   END SHIP_TO_CUSTOMER_KEY,
   CASE
      WHEN A.SOLD_TO_CUSTOMER_KEY >= -1001800
      AND A.SOLD_TO_CUSTOMER_KEY <= -1000000
         THEN -999
      ELSE A.SOLD_TO_CUSTOMER_KEY
   END SOLD_TO_CUSTOMER_KEY,
   CASE
      WHEN A.END_CUSTOMER_KEY >= -1001800
      AND A.END_CUSTOMER_KEY <= -1000000
         THEN -999
      ELSE A.END_CUSTOMER_KEY
   END END_CUSTOMER_KEY,
   CASE
      WHEN A.DV_END_CUSTOMER_KEY >= -1001800
      AND A.DV_END_CUSTOMER_KEY <= -1000000
         THEN -999
      WHEN A.DV_END_CUSTOMER_KEY >= -1006800
      AND A.DV_END_CUSTOMER_KEY <= -1005000
         THEN -888
      WHEN A.DV_END_CUSTOMER_KEY >= -1011800
      AND A.DV_END_CUSTOMER_KEY <= -1010000
         THEN -777
      ELSE A.DV_END_CUSTOMER_KEY
   END DV_END_CUSTOMER_KEY,
   CASE
      WHEN A.SALES_TERRITORY_KEY >= -1001800
      AND A.SALES_TERRITORY_KEY <= -1000000
         THEN -999
      ELSE A.SALES_TERRITORY_KEY
   END SALES_TERRITORY_KEY,
   CASE
      WHEN B.PARTNER_SITE_PARTY_KEY >= -1003000
      AND B.PARTNER_SITE_PARTY_KEY <= -1000000
         THEN -999
      ELSE B.PARTNER_SITE_PARTY_KEY
   END PARTNER_SITE_PARTY_KEY,
   B.CHANNEL_BOOKINGS_FLG,
   B.CHANNEL_DROP_SHIP_FLG,
   CASE
      WHEN B.AS_OF_FSC_MTH_PTR_STE_PRTY_KEY >= -1003000
      AND B.AS_OF_FSC_MTH_PTR_STE_PRTY_KEY <= -1000000
         THEN -999
      ELSE B.AS_OF_FSC_MTH_PTR_STE_PRTY_KEY
   END AS_OF_FSC_MTH_PTR_STE_PRTY_KEY,
   B.AS_OF_FSC_MTH_CHANNEL_BKGS_FLG,
   B.AS_OF_FSC_MTH_CHNL_DRP_SHP_FLG,
   B.DV_DRCT_VAL_ADDED_DSTI_ORD_FLG,
   A.SALES_REP_NUMBER AS SALES_REP_NUM,
   A.DV_FISCAL_YEAR_MTH_NUMBER_INT AS FISCAL_YEAR_MONTH_INT,
   A.ADJUSTMENT_TYPE_CODE AS ADJUSTMENT_TYPE_CD,
   A.SALES_CHANNEL_CODE AS SALES_CHANNEL_CD,
   A.SALES_CREDIT_TYPE_CODE AS SALES_CREDIT_TYPE_CD,
   A.IDE_ADJUSTMENT_CODE AS IDE_ADJUSTMENT_CD,
   A.ADJUSTMENT_CODE AS ADJUSTMENT_CD,
   A.BKGS_MEASURE_TRANS_TYPE_CODE AS BKGS_MEASURE_TRANS_TYPE_CD,
   A.ACQUISITION_FLG,
   A.DISTRIBUTOR_OFFSET_FLG,
   A.CORPORATE_BOOKINGS_FLG,
   A.DV_REVENUE_RECOGNITION_FLG /* ADDED PART OF TRUE DEMAND */,
   A.DV_NET_SPREAD_FLG /* ADDED PART OF TRUE DEMAND */,
   A.OVERLAY_FLG,
   A.IC_REVENUE_FLG,
   A.CHARGES_FLG,
   A.SALESREP_FLG,
   A.MISC_FLG,
   A.SERVICE_FLG,
   A.INTERNATIONAL_DEMO_FLG,
   A.REPLACEMENT_DEMO_FLG,
   A.REVENUE_FLG,
   A.RMA_FLG,
   A.WIPS_ORIGINATOR_ID_INT,
   A.CONVERSION_RT,
   NULL AS DD_CISCO_BOOKED_DTM,
   A.CONVERSION_DT,
   NSAL.REPORTED_SALES_ORDER_NUM_LINT AS DV_SOURCE_ORDER_NUM,
   CASE
      WHEN A.BK_POS_TRANSACTION_ID_INT >= -1003000
      AND A.BK_POS_TRANSACTION_ID_INT <= -1000000
         THEN -999
      ELSE A.BK_POS_TRANSACTION_ID_INT
   END BK_POS_TRANSACTION_ID_INT,
   A.DD_BK_SO_NUMBER_INT AS DD_BK_SO_NUM_INT,
   A.DD_SLS_ORD_OPERATING_UNIT_CD,
   CASE
      WHEN A.ADJUSTMENT_DESCR_KEY >= -1001800
      AND A.ADJUSTMENT_DESCR_KEY <= -1000000
         THEN NULL
      ELSE A.ADJUSTMENT_DESCR_KEY
   END ADJUSTMENT_DESCR_KEY,
   A.DD_TRX_CURRENCY_CD,
   A.DV_TRANSACTION_TYPE,
   SUM(A.TRADE_IN_AMOUNT) AS TRADE_IN_AMT,
   SUM(A.DD_COMP_US_NET_PRICE_AMOUNT) AS COMP_US_NET_PRICE_AMT,
   SUM(A.DD_COMP_US_LIST_PRICE_AMOUNT) AS COMP_US_LIST_PRICE_AMT,
   SUM(A.DD_COMP_US_COST_AMOUNT) AS COMP_US_COST_AMT,
   SUM(A.DD_EXTENDED_QUANTITY) AS EXTENDED_QTY,
   SUM(A.DD_COMP_US_HOLD_NET_PRICE_AMT) AS COMP_US_HOLD_NET_PRICE_AMT,
   SUM(A.DD_COMP_US_HOLD_LIST_PRICE_AMT) AS COMP_US_HOLD_LIST_PRICE_AMT,
   SUM(A.DD_COMP_US_HOLD_COST_AMOUNT) AS COMP_US_HOLD_COST_AMT,
   SUM(A.DD_EXTENDED_HOLD_QUANTITY) AS EXTENDED_HOLD_QTY,
   SUM(A.DD_COMP_US_STANDARD_PRICE_AMT) AS COMP_US_STANDARD_PRICE_AMT,
   NULL AS DV_BOOKED_DTM,
   NULL AS DV_BOOKED_DT,
   NULL AS ORACLE_BOOKED_DTM,
   NULL AS ORACLE_BOOKED_DT,
   /*,A.EDW_CREATE_DATETIME           
   ,A.EDW_CREATE_USER  
   ,A.EDW_UPDATE_DATETIME                                     
   ,A.EDW_UPDATE_USER */
   A.CANCEL_CODE AS CANCEL_CD,
   CURRENT_TIMESTAMP(0) AS EDW_CREATE_DTM,
   CURRENT_USER() AS EDW_CREATE_USER,
   CURRENT_TIMESTAMP(0) AS EDW_UPDATE_DTM,
   /*Q3FY14 OA */
   CURRENT_USER() AS EDW_UPDATE_USER /* CHG0463914 Adding WHO col updates*/,
   A.DV_ATTRIBUTION_CD,
   CASE
      WHEN A.DV_PRODUCT_KEY >= -1006800
      AND A.DV_PRODUCT_KEY <= -1005000
         THEN -998
      WHEN A.DV_PRODUCT_KEY >= -1001800
      AND A.DV_PRODUCT_KEY <= -1000000
         THEN -999
      ELSE A.DV_PRODUCT_KEY
   END AS DV_PRODUCT_KEY,
   A.DV_FMV_FLG,
   A.REVENUE_TRANSFER_KEY /*FMV Q2FY15*/,
   CLD.CALENDAR_YEAR_INT * 100 + CLD.CALENDAR_MONTH_NUMBER_INT CALENDAR_YEAR_MONTH_INT,
   /*ADDED ATTRIBUTE LOGIC AS PART OF DSV Q1FY16 BY */
   A.DSV_FLG,
   /* PNEELRAJ ADDED AS A PART OF ICPM Q2FY16*/
   B.DV_ROUTE_TO_MARKET_CD,
   /*PNEELRAJ ADDED AS A PART OF ICPM Q2FY16*/
   B.DV_AS_OF_FSC_MTH_RTM_CD,
   A.DV_DEAL_ID /*SOT June CDR*/,
   /* Added by VKOPPURA as part of RO PROJECT RELEASE: Q3FY17 */
   A.XCAT_FLG,
   A.BK_OFFER_TYPE_NAME,
   A.RECURRING_OFFER_FLG,
   A.ELA_FLG,
   SUM(A.DV_PURCHASE_ADJ_DSCNT_USD_AMT) AS DV_PURCHASE_ADJ_DSCNT_USD_AMT /* Q1FY18 PA */,
   A.DV_RECURRING_OFFER_CD /* Q1FY18 RO */,
   SUM(A.DV_BKG_GROSS_MGN_AMOUNT) AS DV_BKG_GROSS_MGN_AMOUNT /*added as part product BGM - Q1FY18 release */,
   SUM(A.DV_BGM_NON_STANDARD_COST_AMT) AS DV_BGM_NON_STANDARD_COST_AMT /*added as part product BGM - Q1FY18 release */,
   A.POB_TYPE_CD,
   A.NRS_TRANSITION_FLG,
   A.SALES_MOTION_CD,
   A.SUMMARY_QUOTE_FLG,
   /*Added below columns as part of Q4FY19 May Acquisition changes*/
   B.DV_DBT_TYP,
   A.ACQUISITION_ORDER_ORIGIN_CD,
   A.ACQUISITION_ROLE,
   a.SALES_ADJUSTMENT_SOURCE_CODE AS SALES_ADJUSTMENT_SOURCE_CODE,
   B.BOOKING_CHANNEL_TYPE,
   A.BUNDLE_TYPE_CD /*ADDED AS PART OF NOAH SCOPE */,
   SUM(A.DV_COMP_US_GROSS_BKG_AMOUNT) AS DV_COMP_US_GROSS_BKG_AMOUNT /*ADDED AS PART OF SFP Q4FY21 REL*/
FROM
   {{ var('m_WI1_RSTD_BKGS_ORDER_MTH_SLSORDVWDB') }}.MT_RSTD_BKGS_MEASURE A,
   {{ var('m_WI1_RSTD_BKGS_ORDER_MTH_SLSORDVWDB') }}.N_BOOKINGS_CHANNEL_MEASURE B,
   {{ var('m_WI1_RSTD_BKGS_ORDER_MTH_SLSORDVWDB') }}.N_SALES_ADJUSTMENT_LINE NSAL,
   {{ var('m_WI1_RSTD_BKGS_ORDER_MTH_STGDB') }}.WI_RSTD_BKGS_REF_MTH_INTS INTS,
   {{ var('m_WI1_RSTD_BKGS_ORDER_MTH_COMREFVWDB') }}.R_FISCAL_DAY_TO_YEAR CLD
WHERE
   A.BOOKINGS_MEASURE_KEY = B.BOOKINGS_MEASURE_KEY
   AND A.BOOKINGS_PROCESS_DATE = B.BOOKINGS_PROCESS_DATE
   AND A.BKGS_MEASURE_TRANS_TYPE_CODE = B.BKGS_MEASURE_TRANS_TYPE_CODE
   AND A.BOOKINGS_MEASURE_KEY = NSAL.BK_SALES_ADJ_LINE_NUMBER_INT
   AND A.BOOKINGS_PROCESS_DATE = NSAL.PROCESS_DATE
   AND COLLATE(A.BKGS_MEASURE_TRANS_TYPE_CODE, 'en-ci-rtrim') = 'SLS_ADJ'
   AND A.DV_FISCAL_YEAR_MTH_NUMBER_INT = INTS.DV_FISCAL_YEAR_MTH_NUMBER_INT
   AND COLLATE(A.RSTD_DEL_RECORD_FLG, 'en-ci-rtrim') = 'N'
   AND CLD.CALENDAR_DATE = A.BOOKINGS_PROCESS_DATE
